      const privatePath = '/private/var/folders/ww/shell-wait-fixture-secret/codex-home';
      const result = inspectShellWaitEvidence(evidenceInput({ rollouts, redactions: [privatePath] }));
      assert.equal(result.status, 'inconclusive');
