        gatePath: 'unused-gate',
        captureProcessIdentity: async () => identity,
        readProcessIdentity: async () => identity,
        terminateProcessIdentity: async () => ({ attempted: true, signalled: 'SIGTERM', exited: true, failure: null }),
        releaseGate: async () => {},
        sleep: async () => {},
